import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Seemantha Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/47-seemantha-profile.md","filePath":"reference/47-seemantha-profile.md","lastUpdated":1788720195000}'),n={name:"reference/47-seemantha-profile.md"};function s(o,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="seemantha-source-profile" tabindex="-1">Seemantha Source Profile <a class="header-anchor" href="#seemantha-source-profile" aria-label="Permalink to &quot;Seemantha Source Profile&quot;">​</a></h1><h2 id="authority-and-scope" tabindex="-1">Authority and scope <a class="header-anchor" href="#authority-and-scope" aria-label="Permalink to &quot;Authority and scope&quot;">​</a></h2><p>The <code>seemantha</code> activity is linked to the verified claim <code>muhurta.seemantha</code>. Its authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter VII, “Seemantha,” internal printed pages 21–22 (physical PDF pages 24–25 of the inspected 2020 Chistabo derivative). Raman is a modern secondary synthesis, not primary scripture; this status means the implemented criteria match this inspected passage within its stated scope.</p><p>The profile also exposes the related contradicted claim <code>muhurta.seemantha.chintamani_divergence</code>, from <em>Muhurta Chintamani</em>, Samskara-prakarana verse 8, printed page 77 (OCR lines 4157–4180). This is not used to launder Raman&#39;s profile into universal authority; it records where an independent classical passage agrees and disagrees.</p><p>Raman treats Seemantha as a prenatal rite for the first pregnancy, normally in the fifth or seventh month. If that schedule cannot be kept, it reports the view of sage Sankha that the rite should still occur before delivery. The calendar month is not the pregnancy month, so the finder cannot automate this prerequisite and displays it as a practitioner check.</p><p>Muhurta Chintamani instead prescribes the sixth or eighth month. It corroborates the automated Tithi exclusions, includes the profile&#39;s nine stars across its primary and alternative lists, supplies the same Monday/Wednesday/Thursday/ Friday alternative, and likewise relaxes Guru/Shukra combustion. Its male-planet Lagna/Navamsha and house-placement formulation differs from Raman&#39;s ten admitted Rasis. A family must choose its lineage with a qualified practitioner; the product does not call either pregnancy-month rule universal.</p><h2 id="automated-crosswalk" tabindex="-1">Automated crosswalk <a class="header-anchor" href="#automated-crosswalk" aria-label="Permalink to &quot;Automated crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>Inspected passage</th><th>Implementation</th></tr></thead><tbody><tr><td>Nakshatra</td><td>Raman&#39;s nine primary stars; all occur across Chintamani&#39;s primary and alternative lists</td><td>Exact Raman admission list</td></tr><tr><td>Tithi</td><td>Reject Chaturthi, Shashthi, Ashtami, Navami, Chaturdashi and Amavasya</td><td>Exact Paksha-qualified admission list</td></tr><tr><td>Vara</td><td>Raman rejects Sunday, Tuesday and Saturday; Chintamani gives the admitted set as an alternative</td><td>Monday, Wednesday, Thursday and Friday admitted</td></tr><tr><td>Lagna</td><td>Reject Simha and Vrischika</td><td>The remaining ten Rasis admitted</td></tr><tr><td>Pournami</td><td>Allowed only when Chandra is dignified</td><td>Conservatively omitted pending chart judgment</td></tr><tr><td>Combustion</td><td>Pregnancy month takes precedence; Guru/Shukra combustion may be ignored</td><td>No combustion gate</td></tr></tbody></table><h2 id="browser-computed-chart-and-personal-checks" tabindex="-1">Browser-computed chart and personal checks <a class="header-anchor" href="#browser-computed-chart-and-personal-checks" aria-label="Permalink to &quot;Browser-computed chart and personal checks&quot;">​</a></h2><p>For Drik browser results, the eighth house must be vacant and Chandra must stay outside the eighth across every sampled state. Selecting the mother also enables the inclusive birth-star count: the 3rd, 7th, 8th, 10th and 22nd candidate Nakshatras are rejected at any sample. Samples cover the window edges and both sides of every known interior Drik Lagna transition. Python/MCP continue to expose these as manual wording because they do not call the chart service. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><h2 id="practitioner-checks" tabindex="-1">Practitioner checks <a class="header-anchor" href="#practitioner-checks" aria-label="Permalink to &quot;Practitioner checks&quot;">​</a></h2><ul><li>Confirm that this is the first pregnancy and choose the pregnancy-month rule with a qualified practitioner: Raman gives the fifth/seventh month and Chintamani verse 8 gives the sixth/eighth.</li><li>Ashwini, Anuradha and Moola are only unavoidable-circumstance alternatives; they are not included in automatic results.</li><li>Admit Pournami only after judging Chandra dignified.</li></ul><h2 id="safety-boundary" tabindex="-1">Safety boundary <a class="header-anchor" href="#safety-boundary" aria-label="Permalink to &quot;Safety boundary&quot;">​</a></h2><p>The profile schedules a cultural ceremony; it does not assess pregnancy or maternal/fetal health. Maternal comfort, clinician instructions and timely medical care always override electional timing. No result predicts a medical outcome.</p><h2 id="cross-surface-contract" tabindex="-1">Cross-surface contract <a class="header-anchor" href="#cross-surface-contract" aria-label="Permalink to &quot;Cross-surface contract&quot;">​</a></h2><p>The Python rules are the source of truth. The generated browser contract and MCP <code>activity_profile</code> expose the same claim, hard gates and manual checks. Tests protect the exact source crosswalk, reject accidental generic samskara filters and require catalogue parity. Pregnancy-month, lineage and Pournami dignity prerequisites remain unresolved, so <code>manual_prerequisites</code> caps every result below <code>Excellent</code> until practitioner review; a high relative score never hides that uncertainty.</p>',16)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
